import { invoke } from "@tauri-apps/api/core"
import type Database from "@tauri-apps/plugin-sql"

// Kept apart from transaction.ts (which needs getDB) so that initDb can run a transaction on a database that is still being opened

/**
 * Reference to the id generated by an earlier statement of the same transaction:
 * the Rust command replaces it with `results[$ref].lastInsertId - offset`.
 * @category Database
 */
export type TxRef = { $ref: number, offset: number }

/**
 * One statement of a transaction. A param can be a plain value or a TxRef.
 * @category Database
 */
export type TxStatement = { sql: string, params: unknown[] }

/**
 * Outcome of one statement of a transaction (same fields as the plugin's QueryResult).
 * @category Database
 */
export type TxResult = { rowsAffected: number, lastInsertId: number }

/**
 * Error of a failed transaction: nothing was written. `statementIndex` is the failing statement (null when unknown).
 * The message keeps the driver text (e.g. "UNIQUE constraint failed"), so handleDBError can classify it.
 * @category Database
 */
export class TransactionError extends Error {
    readonly statementIndex: number | null

    constructor(message: string, statementIndex: number | null) {
        super(message)
        this.name = "TransactionError"
        this.statementIndex = statementIndex
    }
}

/**
 * Runs the statements in ONE real SQLite transaction on the given connection (Rust command `db_transaction`, which finds
 * the pool by `db.path`): all of them are committed together or none is.
 * @throws A TransactionError (with the failing statement index) when a statement fails; the transaction is rolled back.
 * @category Database
 */
export async function runTransactionOn(db: Database, statements: TxStatement[]): Promise<TxResult[]> {
    if (statements.length === 0) return []
    try {
        return await invoke<TxResult[]>("db_transaction", { db: db.path, statements })
    } catch (error: unknown) {
        const message = error instanceof Error ? error.message : String(error)
        const match = /^statement (\d+)/.exec(message)
        throw new TransactionError(message, match ? Number(match[1]) : null)
    }
}
